using UnityEngine;using UnityEngine.AI;using System.IO;using System.Collections;using System.Linq;
public class HunterTorchCorrectionProbe:MonoBehaviour {
 [System.Serializable]public class GripData{public Vector3 position;public Quaternion rotation;}
 string dir;HunterTorchPose pose;HunterGameplayAnimator bridge;Camera cameraView;DemoCamera follow;DemoMovement movement;
 void Frame(float angle){var offset=Quaternion.Euler(0,angle,0)*new Vector3(0,1.45f,3.6f);cameraView.transform.position=transform.position+offset;cameraView.transform.LookAt(transform.position+Vector3.up*1.15f);}
 void Log(string stage){var torch=GetComponentsInChildren<Transform>(true).First(t=>t.name=="Hunter Left Torch");File.AppendAllText(dir+"/playmode.txt",stage+" state="+bridge.CurrentVisualState+" weight="+pose.Weight+" leftHand="+bridge.animator.GetBoneTransform(HumanBodyBones.LeftHand).position+" rightHand="+bridge.animator.GetBoneTransform(HumanBodyBones.RightHand).position+" gripDelta="+Vector3.Distance(torch.position,Vector3.Lerp(bridge.animator.GetBoneTransform(HumanBodyBones.LeftHand).position,(bridge.animator.GetBoneTransform(HumanBodyBones.LeftIndexProximal).position+bridge.animator.GetBoneTransform(HumanBodyBones.LeftLittleProximal).position)*.5f,.68f))+" socketPositionError="+Vector3.Distance(torch.position,pose.Grip.position)+" socketRotationError="+Quaternion.Angle(torch.rotation,pose.Grip.rotation)+" particles="+string.Join(",",torch.GetComponentsInChildren<ParticleSystem>().Select(p=>p.name+":"+p.isPlaying+":"+p.particleCount))+"\n");}
 IEnumerator Start(){dir=Path.GetFullPath("Evidence/hunter-torch-correction-20261030");Directory.CreateDirectory(dir);File.WriteAllText(dir+"/playmode.txt","Unity="+Application.unityVersion+" scene="+gameObject.scene.name+"\nDirect behavior calls; not keyboard simulation.\n");pose=GetComponent<HunterTorchPose>();bridge=GetComponent<HunterGameplayAnimator>();movement=GetComponent<DemoMovement>();cameraView=movement.viewCamera;follow=cameraView.GetComponent<DemoCamera>();if(follow)follow.enabled=false;
 yield return new WaitForSeconds(.3f);var grip=pose.Grip;if(grip)File.WriteAllText(dir+"/grip.json",JsonUtility.ToJson(new GripData{position=grip.localPosition,rotation=grip.localRotation}));
 yield return new WaitForSeconds(1);Frame(0);var torch=bridge.animator.GetComponentsInChildren<Transform>(true).First(t=>t.name=="Hunter Left Torch");torch.gameObject.SetActive(false);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(dir+"/lighting_visual_off.png");torch.gameObject.SetActive(true);yield return new WaitForSeconds(.6f);for(int i=0;i<3;i++){Frame(i*90);yield return new WaitForSeconds(.3f);Log("idle"+i);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(dir+"/idle_"+i+".png");}
 var agent=GetComponent<NavMeshAgent>();Vector3 start=transform.position;var target=start+transform.forward*5;if(NavMesh.SamplePosition(target,out var nav,3,NavMesh.AllAreas))agent.SetDestination(nav.position);yield return new WaitForSeconds(.65f);Frame(45);File.AppendAllText(dir+"/playmode.txt","moved="+Vector3.Distance(start,transform.position)+" path="+agent.pathStatus+" velocity="+agent.velocity+"\n");Log("moving");ScreenCapture.CaptureScreenshot(dir+"/moving.png");yield return new WaitForSeconds(.8f);movement.TakeManualControl();bool dodge=movement.TryDodge(transform.forward);yield return new WaitForSeconds(.32f);Frame(45);Log("dodge");File.AppendAllText(dir+"/playmode.txt","dodgeAccepted="+dodge+" duration="+movement.dodgeDuration+" invul="+movement.IsInvulnerable+"\n");ScreenCapture.CaptureScreenshot(dir+"/dodge.png");yield return new WaitForSeconds(.7f);Log("recovered");
 var flow=GetComponent<DemoPrologueFlow>();if(flow&&flow.enemy){flow.BeginHunt();var enemy=flow.enemy.GetComponent<DemoEnemy>();var ea=enemy.GetComponent<NavMeshAgent>();ea.Warp(transform.position+transform.forward*1.3f);int before=enemy.Health;movement.SelectEnemy(enemy);yield return new WaitForSeconds(.25f);Frame(45);Log("attack");ScreenCapture.CaptureScreenshot(dir+"/attack.png");for(int frame=0;frame<12;frame++){yield return new WaitForSeconds(.05f);Log("attack_frame"+frame);if(frame%3==0)ScreenCapture.CaptureScreenshot(dir+"/attack_frame"+frame+".png");}yield return new WaitForSeconds(.65f);File.AppendAllText(dir+"/playmode.txt","enemyHP="+before+" -> "+enemy.Health+" message="+movement.message+"\n");movement.TakeManualControl();}
 yield return new WaitForSeconds(1);Log("end");if(follow)follow.enabled=true;}
}
